const DNAME: Record<string, string> = { street: "Street", wangan: "Wangan", touge: "Touge" };
const RUNG_NAME: Record<string, string> = { kid1: "Kid 1", kid2: "Kid 2", mat1: "Mature 1", mat2: "Mature 2", oh1: "Old head 1", oh2: "Old head 2", boss: "Boss" };
const usd = (x: number) => "$" + Math.round(x).toLocaleString("en-US");
const money = (x: number) => {
  const r = Math.round(x * 100 + (x < 0 ? -1e-9 : 1e-9)) / 100;
  const a = Math.abs(r);
  const body = "$" + a.toLocaleString("en-US", { minimumFractionDigits: Math.abs(a - Math.round(a)) < 1e-9 ? 0 : 2, maximumFractionDigits: 2 });
  return r < 0 ? "−" + body : body;
};
const moneyS = (x: number) => (x > 0 ? "+" : x < 0 ? "−" : "") + money(Math.abs(x));
const pc = (x: number) => x.toFixed(1) + "%";
const num = (s: string) => { const x = parseFloat(s); return isFinite(x) ? x : 0; };
const toneOf = (w: number): "success" | "warning" | "danger" => (w >= 60 ? "success" : w >= 50 ? "warning" : "danger");
const f1 = (a: number[]) => a.map((x) => x.toFixed(1)).join(" / ");
function raceName(r: Row): string {
  if (r.era[0] === "R") return r.era + " " + RUNG_NAME[r.id.split(" ")[1]];
  return r.label;
}
function unlockText(u: string): string {
  const [a, b] = u.split(":");
  if (a === "open") return "R" + (Number(b) + 1) + " start";
  if (a === "arc") return "after the " + b + " win";
  return "after the R" + (Number(a) + 1) + " " + RUNG_NAME[b] + " win";
}
function grindPurseOf(r: Row): number {
  return r.era[0] === "R" ? purse(r.stage, "kid", true) : C.ARC_GRIND_PAY;
}
function storyPurseOf(r: Row): number {
  if (r.era[0] === "R") return purse(r.stage, C.KIND[C.RUNGS.indexOf(r.id.split(" ")[1])], false);
  if (r.billed) return C.FIN_PURSE;
  const a = C.ARC.find((x: any) => x.id === r.id);
  return a ? a.purse : 0;
}
function takeDebt(pay: number, debt: number): { toDebt: number; net: number; debt: number } {
  if (debt > 0) { const toDebt = Math.min(debt, C.DEBT_SHARE * pay); return { toDebt, net: pay - toDebt, debt: debt - toDebt }; }
  return { toDebt: 0, net: pay, debt: 0 };
}
type GrindLine = { from: number; to: number; purse: number; toDebt: number; net: number; debtLeft: number };
type BuyLine = { label: string; price: number };
function cashPool(r: Row, prev: Row | null) {
  const arrival = r.cashBefore;
  const arrivalDebt = prev ? prev.debtAfter : C.DEBT;
  const gPay = grindPurseOf(r);
  const n = r.grindsAuto + r.grindsExtra;
  let debt = arrivalDebt;
  const grindLines: GrindLine[] = [];
  let run: { from: number; purse: number; toDebt: number; net: number } | null = null;
  let grindNet = 0, grindToDebt = 0;
  for (let i = 1; i <= n; i++) {
    const t = takeDebt(gPay, debt);
    if (run && (run.toDebt !== t.toDebt || run.net !== t.net || run.purse !== gPay)) {
      grindLines.push({ from: run.from, to: i - 1, purse: run.purse, toDebt: run.toDebt, net: run.net, debtLeft: debt });
      run = null;
    }
    debt = t.debt; grindNet += t.net; grindToDebt += t.toDebt;
    if (!run) run = { from: i, purse: gPay, toDebt: t.toDebt, net: t.net };
  }
  if (run) grindLines.push({ from: run.from, to: n, purse: run.purse, toDebt: run.toDebt, net: run.net, debtLeft: debt });
  const debtNow = debt;
  const next = takeDebt(gPay, debtNow);
  const autoBuys: BuyLine[] = [], plannedBuys: BuyLine[] = [];
  for (const s of r.bought) {
    const m = /^(.+)\s+\$(\d+)$/.exec(s);
    if (m) plannedBuys.push({ label: m[1], price: Number(m[2]) });
    else autoBuys.push({ label: s, price: modPrice(s, false, r.wholesale) });
  }
  const autoSpend = autoBuys.reduce((s, b) => s + b.price, 0);
  const plannedSpend = plannedBuys.reduce((s, b) => s + b.price, 0);
  const spendNow = r.cashAtBuy - plannedSpend;
  const storyPay = storyPurseOf(r);
  const story = takeDebt(storyPay, debtNow);
  const cashAfterWin = spendNow + story.net;
  const purseName = r.billed ? "Finale purse" : r.era === "Arc" ? "Arc purse" : "Story purse";
  return {
    arrival, arrivalDebt, gPay, n, grindLines, grindNet, grindToDebt, next, debtNow,
    autoBuys, autoSpend, plannedBuys, plannedSpend, spendNow, storyPay, story, cashAfterWin, purseName,
  };
}
