const PY = { mins: [53.0, 54.4, 50.5], bosses: [53.0, 57.7, 55.8], cap6060: [31.6, 40.1, 30.2], cap8080: [94.9, 91.6, 92.9], finale: [81.7, 82.7, 79.3, 81.7] };

// Keep the clicked control still: a re-render remounts tables and updates Metrics / LineChart
// and the inspector, which otherwise jumps the scroll. Pin any click on a [data-pin] node.
const pinId = (id: string) => "pin-" + id.replace(/\s+/g, "-");
type ScrollPin = { id: string; y: number; spots: { top: number; left: number; set: (t: number, l: number) => void }[] };
function pinNode(id: string): HTMLElement | null {
  return typeof document === "undefined" ? null : document.getElementById(id);
}
function scrollSpots(from: Element | null): ScrollPin["spots"] {
  const spots: ScrollPin["spots"] = [];
  const seen = new Set<Element | Window>();
  const addWin = () => {
    if (seen.has(window)) return;
    seen.add(window);
    spots.push({ top: window.scrollY, left: window.scrollX, set: (t, l) => window.scrollTo(l, t) });
  };
  const addEl = (node: Element) => {
    if (seen.has(node)) return;
    seen.add(node);
    const el = node as HTMLElement;
    spots.push({ top: el.scrollTop, left: el.scrollLeft, set: (t, l) => { el.scrollTop = t; el.scrollLeft = l; } });
  };
  addWin();
  let n: Element | null = from;
  while (n) {
    const st = getComputedStyle(n);
    if (/(auto|scroll|overlay)/.test(st.overflowY) || /(auto|scroll|overlay)/.test(st.overflowX)) addEl(n);
    n = n.parentElement;
  }
  return spots;
}
function capturePin(id: string, ev?: any): ScrollPin {
  const t: Element | null = ev && ev.currentTarget ? ev.currentTarget : ev && ev.target ? ev.target : null;
  const node: Element | null = (t && t.closest ? t.closest("[data-pin]") : null) || pinNode(id);
  return { id, y: node ? node.getBoundingClientRect().top : 0, spots: scrollSpots(node || t) };
}
function applyPin(pin: ScrollPin, node?: Element | null) {
  const el = node || pinNode(pin.id);
  for (const s of pin.spots) s.set(s.top, s.left);
  if (!el) return;
  const nudge = () => {
    const dy = el.getBoundingClientRect().top - pin.y;
    if (Math.abs(dy) < 1) return false;
    let n: Element | null = el.parentElement; let used = false;
    while (n) {
      const st = getComputedStyle(n);
      if (/(auto|scroll|overlay)/.test(st.overflowY) && (n as HTMLElement).scrollHeight > (n as HTMLElement).clientHeight + 1) {
        (n as HTMLElement).scrollTop += el.getBoundingClientRect().top - pin.y; used = true;
      }
      n = n.parentElement;
    }
    const dy2 = el.getBoundingClientRect().top - pin.y;
    if (Math.abs(dy2) >= 1) window.scrollBy(0, dy2);
    return used || Math.abs(dy2) >= 1;
  };
  nudge();
}

export default function CampaignPlanner() {
  const theme = useGrokTheme();
  const [prof, setProf] = useState<string>("c8080");
  const [cRead, setCRead] = useState<string>("70");
  const [cTime, setCTime] = useState<string>("70");
  const [policy, setPolicy] = useState<Policy>("story");
  const [target, setTarget] = useState<string>("50");
  const [autoBuy, setAutoBuy] = useState<boolean>(true);
  const [buildMode, setBuildMode] = useState<BuildMode>("auto");
  const [tgt, setTgt] = useState<Record<string, string[]>>({ street: ["50", "25", "25"], wangan: ["25", "25", "50"], touge: ["45", "25", "30"] });
  const [extra, setExtra] = useState<Record<string, number>>({});
  const [buys, setBuys] = useState<Buy[]>([]);
  const [retry, setRetry] = useState<Record<string, boolean>>({});
  const [sel, setSel] = useState<string>("R1 kid1");
  const [shopId, setShopId] = useState<string>("MOD_R1_POW_MK1");
  const [shopAero, setShopAero] = useState<boolean>(false);

  const read = prof === "custom" ? clamp(num(cRead), 60, 80) : Number(prof.slice(1, 3));
  const time = prof === "custom" ? clamp(num(cTime), 60, 80) : Number(prof.slice(3, 5));
  const tgtErr: string[] = [];
  const targets: Record<string, Alloc> = {};
  for (const d of C.ROUNDS as string[]) {
    const v = tgt[d].map(num);
    if (v.some((x) => x < 25 || x > 50) || Math.abs(v[0] + v[1] + v[2] - 100) > 0.01) tgtErr.push(DNAME[d]);
    else targets[d] = [v[0], v[1], v[2]];
  }
  const tgtN = Number(target);
  const plan: Plan = { read, time, policy, target: tgtN, autoBuy, buildMode, targets, extra, buys };
  const key = JSON.stringify(plan);
  const rows = useMemo(() => simulate(plan), [key]);
  const ver = useMemo(() => {
    const s = simulate({ read: 80, time: 80, policy: "story", target: 50, autoBuy: true, buildMode: "auto", targets: {}, extra: {}, buys: [] });
    const cap = bossAtCap();
    return {
      mins: [0, 1, 2].map((k) => Math.min(...s.slice(7 * k, 7 * k + 7).map((r) => r.show))),
      bosses: [6, 13, 20].map((i) => s[i].show),
      cap6060: cap.map((x) => x[0]), cap8080: cap.map((x) => x[1]),
      finale: s.filter((r) => r.billed).map((r) => r.show),
    };
  }, []);

  const pinRef = useRef<ScrollPin | null>(null);
  const hold = (id: string, ev?: any) => { pinRef.current = capturePin(id, ev); };
  const attachPin = (id: string) => (el: HTMLDivElement | null) => {
    const p = pinRef.current;
    if (el && p && p.id === id) applyPin(p, el);
  };
  useEffect(() => {
    const arm = (ev: any) => {
      if (ev.type === "keydown" && ev.key !== "Enter" && ev.key !== " ") return;
      const t: Element | null = ev && ev.target ? ev.target : null;
      const node: Element | null = t && t.closest ? t.closest("[data-pin]") : null;
      const id = node && (node as HTMLElement).id ? (node as HTMLElement).id : "pin-page";
      pinRef.current = capturePin(id, ev);
    };
    document.addEventListener("pointerdown", arm, true);
    document.addEventListener("keydown", arm, true);
    return () => {
      document.removeEventListener("pointerdown", arm, true);
      document.removeEventListener("keydown", arm, true);
    };
  }, []);
  const viewKey = [key, sel, shopId, String(shopAero), JSON.stringify(retry), prof, cRead, cTime, JSON.stringify(tgt)].join("|");
  useEffect(() => {
    const p = pinRef.current;
    if (!p) return;
    const run = () => { if (pinRef.current === p) applyPin(p); };
    run();
    const a = requestAnimationFrame(run);
    const b = requestAnimationFrame(() => requestAnimationFrame(run));
    const t = window.setTimeout(() => { run(); if (pinRef.current === p) pinRef.current = null; }, 160);
    return () => { cancelAnimationFrame(a); cancelAnimationFrame(b); window.clearTimeout(t); };
  }, [viewKey]);

  const idx = Math.max(0, rows.findIndex((r) => r.id === sel));
  const cur = rows[idx];
  const prev = idx > 0 ? rows[idx - 1] : null;
  const pool = cashPool(cur, prev);
  const ladder = rows.filter((r) => r.era[0] === "R");
  const arc = rows.filter((r) => r.era === "Arc");
  const fin = rows.filter((r) => r.billed);
  const minOf = (rs: Row[]) => rs.reduce((m, r) => (r.show < m.show ? r : m), rs[0]);
  const lowLadder = minOf(ladder), lowArc = minOf(arc);
  const gAuto = rows.reduce((s, r) => s + r.grindsAuto, 0), gMine = rows.reduce((s, r) => s + r.grindsExtra, 0);
  const extraTries = rows.reduce((s, r) => s + (retry[r.id] ? 100 / Math.max(r.show, 0.1) - 1 : 0), 0);
  const last = rows[rows.length - 1];

  const autoFill = () => {
    const s = simulate({ ...plan, policy: "mine", extra: {} });
    const e: Record<string, number> = {};
    for (const r of s) if (r.grindsAuto) e[r.id] = r.grindsAuto;
    setExtra(e); setPolicy("story");
  };
  const tag = (r: Row) => {
    const g = r.grindsAuto + r.grindsExtra;
    if (r.show < tgtN) return <Status key={"t" + r.id} tone="danger">{r.L >= r.capL ? "Below target at cap" : "Below target"}</Status>;
    if (g > 0 && r.natural < tgtN) return <Status key={"t" + r.id} tone="warning">Held up by grinds</Status>;
    if (r.natural >= Math.min(99, tgtN + 25)) return <Status key={"t" + r.id} tone="success">Naturally high</Status>;
    return <Status key={"t" + r.id} tone="neutral">On its own</Status>;
  };
  const heldN = rows.filter((r) => r.grindsAuto + r.grindsExtra > 0 && r.natural < tgtN && r.show >= tgtN).length;
  const setN = (id: string, n: number) => setExtra({ ...extra, [id]: Math.max(0, n) });
  const setT = (d: string, i: number, v: string) => { const a = tgt[d].slice(); a[i] = v; setTgt({ ...tgt, [d]: a }); };
  const go = (i: number) => setSel(rows[Math.min(rows.length - 1, Math.max(0, i))].id);
  const press = (pid: string, ev: any, fn: () => void) => { if (ev && ev.preventDefault) ev.preventDefault(); hold(pid, ev); fn(); };
  const tgtDefault: Record<string, string[]> = { street: ["50", "25", "25"], wangan: ["25", "25", "50"], touge: ["45", "25", "30"] };
  const isDefault = (
    prof === "c8080" && policy === "story" && target === "50" && autoBuy && buildMode === "auto"
    && Object.keys(extra).every((k) => !extra[k]) && buys.length === 0 && Object.values(retry).every((v) => !v)
    && sel === "R1 kid1" && !shopAero && shopId === "MOD_R1_POW_MK1" && cRead === "70" && cTime === "70"
    && JSON.stringify(tgt) === JSON.stringify(tgtDefault)
  );
  const reset = () => {
    if (!isDefault && typeof window !== "undefined" && typeof window.confirm === "function") {
      if (!window.confirm("Reset the planner to its default state?")) return;
    }
    setProf("c8080"); setCRead("70"); setCTime("70"); setPolicy("story"); setTarget("50");
    setAutoBuy(true); setBuildMode("auto"); setTgt({ street: ["50", "25", "25"], wangan: ["25", "25", "50"], touge: ["45", "25", "30"] });
    setExtra({}); setBuys([]); setRetry({}); setSel("R1 kid1"); setShopId("MOD_R1_POW_MK1"); setShopAero(false);
  };

  function grindCell(r: Row, where: string = "row"): ReactNode {
    const n = extra[r.id] || 0;
    const pid = pinId(r.id) + "-" + where;
    return (
      <div key={"g" + r.id + where} id={pid} data-pin={pid} ref={attachPin(pid)} style={{ display: "flex", alignItems: "center", gap: 6, flexWrap: "nowrap", overflowAnchor: "auto" }}>
        <Button label="−" variant="quiet" disabled={n === 0} onClick={(ev?: any) => press(pid, ev, () => setN(r.id, n - 1))} />
        <span style={{ minWidth: 56, flex: "0 0 auto", color: theme.text.primary }}>{r.grindsAuto + r.grindsExtra}{r.grindsAuto ? " (" + r.grindsAuto + " auto)" : ""}</span>
        <Button label="+" variant="quiet" disabled={r.L >= r.capL} onClick={(ev?: any) => press(pid, ev, () => setN(r.id, n + 1))} />
      </div>
    );
  }
  const ladderRows = rows.map((r) => [
    <div key={"b" + r.id} id={pinId("sel-" + r.id)} data-pin={pinId("sel-" + r.id)} ref={attachPin(pinId("sel-" + r.id))} style={{ overflowAnchor: "auto" }}>
      <Button label={raceName(r)} variant={r.id === cur.id ? "primary" : "quiet"} onClick={(ev?: any) => press(pinId("sel-" + r.id), ev, () => setSel(r.id))} />
    </div>,
    DNAME[r.d] + " · " + r.T + " turns" + (r.boss ? " · hardest track" : ""),
    grindCell(r),
    "L" + r.L + (r.L >= r.capL ? " (cap)" : ""),
    usd(r.cashAtBuy),
    r.power.toFixed(1),
    r.r.toFixed(3),
    pc(r.natural),
    { text: pc(r.show), tone: toneOf(r.show) },
    tag(r),
    retry[r.id] ? (100 / Math.max(r.show, 0.1)).toFixed(2) : "1",
  ]);

  const pat: string = C.PATTERN[cur.d];
  const slotRows = cur.equipped.map((lab, i) => [
    "Slot " + (i + 1) + " · " + STATK[pat[i]],
    lab === "stock" ? "Stock part" : lab,
    String(lab === "stock" ? C.STOCK : MOD[lab.split(" ")[0]].pts),
  ]);
  const shopPrice = (id: string, aero: boolean) => modPrice(id, aero && cur.aeroOpen, cur.wholesale);
  const shopOpts = C.CATALOG.map((m: any) => {
    const open = cur.done.indexOf(m.u) >= 0;
    const price = shopPrice(m.id, shopAero);
    const short = price - pool.spendNow;
    const aff = !open ? " · locked until " + unlockText(m.u) : short > 1e-9 ? " · unaffordable, need " + money(short) + " more" : " · affordable";
    return { value: m.id as string, label: m.id + " · " + m.st + " " + m.pts + " pts · " + money(price) + aff };
  });
  const hereBuys = buys.map((b, i) => ({ b, i })).filter((x) => x.b.at === cur.id);
  const pickPrice = shopPrice(shopId, shopAero);
  const pickOpen = cur.done.indexOf(MOD[shopId].u) >= 0;
  const pickShort = pickPrice - pool.spendNow;
  const pickAfford = pickOpen && pickShort <= 1e-9;
  const sp = cur.alloc[0] + cur.alloc[1] + cur.alloc[2];
  const share = (k: number) => cur.alloc[k] + " (" + Math.round((100 * cur.alloc[k]) / sp) + "%)";
  const cashMoveRows: any[][] = [
    ["On arrival", "—", "—", money(pool.arrival), money(pool.arrivalDebt)],
  ];
  for (const g of pool.grindLines) {
    const k = g.to - g.from + 1;
    const lab = (g.from === g.to ? "Grind " + g.from : "Grinds " + g.from + "–" + g.to) + (k > 1 ? " × " + k : "");
    cashMoveRows.push([lab, (k > 1 ? k + " × " : "") + money(g.purse), (k > 1 ? k + " × " : "") + moneyS(-g.toDebt), (k > 1 ? k + " × " : "") + moneyS(g.net), money(g.debtLeft)]);
  }
  if (pool.n === 0) cashMoveRows.push(["No grinds yet · next grind would be", money(pool.gPay), moneyS(-pool.next.toDebt), moneyS(pool.next.net), money(pool.next.debt)]);
  for (const b of pool.autoBuys) cashMoveRows.push(["Auto-bought " + b.label, "—", "—", moneyS(-b.price), money(pool.debtNow)]);
  for (const b of pool.plannedBuys) cashMoveRows.push(["Planned " + b.label, "—", "—", moneyS(-b.price), money(pool.debtNow)]);
  cashMoveRows.push(["Available to spend now", "—", "—", money(pool.spendNow), money(pool.debtNow)]);
  cashMoveRows.push([pool.purseName + " (on a win)", money(pool.storyPay), moneyS(-pool.story.toDebt), moneyS(pool.story.net), money(pool.story.debt)]);
  cashMoveRows.push(["After a win", "—", "—", money(Math.abs(cur.cashAfter - pool.cashAfterWin) > 0.05 ? cur.cashAfter : pool.cashAfterWin), money(cur.debtAfter)]);

  const vRows = [
    ["Story only 80/80, lowest race R1 / R2 / R3", PY.mins, ver.mins],
    ["Story only 80/80, boss R1 / R2 / R3", PY.bosses, ver.bosses],
    ["60/60 at level cap, boss R1 / R2 / R3", PY.cap6060, ver.cap6060],
    ["80/80 at level cap, boss R1 / R2 / R3", PY.cap8080, ver.cap8080],
    ["Story only 80/80, finale F1 / F2 / F3 / F4", PY.finale, ver.finale],
  ].map(([label, py, js]) => {
    const a = py as number[], b = js as number[];
    const diff = Math.max(...a.map((x, i) => Math.abs(x - b[i])));
    return [label as string, f1(a), f1(b), <Status key={label as string} tone={diff <= 0.1 + 1e-9 ? "success" : "danger"}>{diff < 1e-9 ? "exact" : "within " + diff.toFixed(1) + " pp"}</Status>];
  });

  return (
    <Page
      title="Campaign planner: live sim"
      summary="Pick a profile, build, grinds and mods, and see level, cash, combat power and the expected win chance for every race from R1 to the F4 finale. Rules: live sim (leftover XP carries over with catch-up XP, live since 2026-11-14). Betting is not included."
      width="wide"
    >
      <Section heading="Setup" actions={<Button label="Reset" onClick={(ev?: any) => press("pin-setup", ev, reset)} />}>
        <div id="pin-setup" data-pin="pin-setup" ref={attachPin("pin-setup")} style={{ overflowAnchor: "auto" }}>
        <Grid columns={2}>
          <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
            <Text>Profile (read / time skill)</Text>
            <Segmented options={PROFILE_OPTS} value={prof} onChange={(v: string) => setProf(v)} />
            {prof === "custom" ? (
              <Grid columns={2}>
                <Input label="Read skill (60–80)" type="number" value={cRead} onChange={(v: string) => setCRead(v)} />
                <Input label="Time skill (60–80)" type="number" value={cTime} onChange={(v: string) => setCTime(v)} />
              </Grid>
            ) : null}
          </div>
          <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
            <Select label="Grinding" options={POLICY_OPTS} value={policy} onChange={(v: Policy) => setPolicy(v)} />
            <Text>{POLICY_HELP[policy]}</Text>
            <div style={{ display: "flex", gap: 8, flexWrap: "wrap", alignItems: "flex-end" }}>
              <Select label="Target win chance" options={TARGET_OPTS} value={target} onChange={(v: string) => setTarget(v)} />
              <Button label="Auto-fill grinds to target" onClick={(ev?: any) => press("pin-setup", ev, autoFill)} />
              <Button label="Reset" onClick={(ev?: any) => press("pin-setup", ev, reset)} />
            </div>
            <Text>Auto-fill writes the fewest grinds that reach the target before each race into the per-race counters (and switches Grinding to story only), so you can fine-tune them with − / +.</Text>
          </div>
          <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
            <Toggle label="Auto-buy mods (the sim's just-in-time buyer)" value={autoBuy} onChange={(v: boolean) => setAutoBuy(v)} />
            <Text>On: before each race and after each grind, buys the unlocked, affordable mod with the largest usable gain (ties go to the cheaper), never past the power cap, no aero. Your planned buys from the race inspector are added on top.</Text>
          </div>
          <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
            <Text>Skill points</Text>
            <Segmented options={[{ value: "auto", label: "Sim build (district tune)" }, { value: "custom", label: "My targets" }]} value={buildMode} onChange={(v: string) => setBuildMode(v as BuildMode)} />
            <Text>New points go toward the target split inside the 25–50% per-stat band; at each district change up to 20% of spent points move toward the new target.</Text>
          </div>
        </Grid>
        {buildMode === "custom" ? (
          <Table
            columns={["District target", "POW %", "HAN %", "EN %"]}
            rows={(C.ROUNDS as string[]).map((d) => [
              DNAME[d],
              ...[0, 1, 2].map((i) => <Input key={d + i} type="number" value={tgt[d][i]} onChange={(v: string) => setT(d, i, v)} />),
            ])}
          />
        ) : null}
        {buildMode === "custom" && tgtErr.length ? (
          <Callout tone="warning" lead="Target not valid">{tgtErr.join(", ") + ": each stat must be 25–50% and the three must add to 100. The district tune is used there until fixed."}</Callout>
        ) : null}
        </div>
      </Section>

      <Section heading={"Race inspector: " + raceName(cur)} id="race-inspector">
        <div id="pin-inspector" data-pin="pin-inspector" ref={attachPin("pin-inspector")} style={{ overflowAnchor: "auto" }}>
        <div id="pin-inspector-nav" data-pin="pin-inspector-nav" ref={attachPin("pin-inspector-nav")} style={{ display: "flex", gap: 8, flexWrap: "wrap", alignItems: "flex-end", overflowAnchor: "auto" }}>
          <Button label="← Previous" disabled={idx === 0} onClick={(ev?: any) => press("pin-inspector-nav", ev, () => go(idx - 1))} />
          <Select label="Race" options={rows.map((r) => ({ value: r.id, label: raceName(r) }))} value={cur.id} onChange={(v: string) => setSel(v)} />
          <Button label="Next →" disabled={idx === rows.length - 1} onClick={(ev?: any) => press("pin-inspector-nav", ev, () => go(idx + 1))} />
        </div>
        <div id="pin-inspector-skill" data-pin="pin-inspector-skill" ref={attachPin("pin-inspector-skill")} style={{ display: "flex", gap: 8, flexWrap: "wrap", alignItems: "center", overflowAnchor: "auto", marginTop: 12 }}>
          <span style={{ color: theme.text.primary }}>Read / QTE timing</span>
          <Segmented options={PROFILE_OPTS} value={prof} onChange={(v: string) => setProf(v)} />
          {prof === "custom" ? (
            <Grid columns={2}>
              <Input label="Read skill (60–80)" type="number" value={cRead} onChange={(v: string) => setCRead(v)} />
              <Input label="Time skill (60–80)" type="number" value={cTime} onChange={(v: string) => setCTime(v)} />
            </Grid>
          ) : null}
        </div>
        <div id="pin-inspector-grinds" data-pin="pin-inspector-grinds" ref={attachPin("pin-inspector-grinds")} style={{ display: "flex", gap: 8, flexWrap: "wrap", alignItems: "center", overflowAnchor: "auto", marginTop: 12 }}>
          <span style={{ color: theme.text.primary }}>Grinds before this race (− / +)</span>
          {grindCell(cur, "insp")}
        </div>
        <div id="pin-inspector-cash" data-pin="pin-inspector-cash" ref={attachPin("pin-inspector-cash")} style={{ overflowAnchor: "auto", marginTop: 16 }}>
          <Text>Cash pool at this stop, live with grind − / + and shop buys. While the $16,000 debt is open, 65% of each purse goes to Sabine and the rest is yours.</Text>
          <Metrics
            metrics={[
              { value: money(pool.arrival), label: "Cash on arrival", detail: "Before this stop's grinds and buys · debt then " + money(pool.arrivalDebt) },
              { value: money(pool.spendNow), label: "Available to spend now", detail: pool.n + " grind" + (pool.n === 1 ? "" : "s") + (pool.autoSpend ? ", auto-bought " + money(pool.autoSpend) : "") + (pool.plannedSpend ? ", planned " + money(pool.plannedSpend) : ""), tone: pool.spendNow >= 1 ? "success" : "warning" },
              { value: money(pool.debtNow), label: "Debt remaining now", detail: pool.debtNow > 0 ? "After these grinds, before the race" : "Debt cleared", tone: pool.debtNow > 0 ? "warning" : "success" },
              { value: money(Math.abs(cur.cashAfter - pool.cashAfterWin) > 0.05 ? cur.cashAfter : pool.cashAfterWin), label: "Cash after a win", detail: pool.purseName + " " + moneyS(pool.storyPay) + ", " + moneyS(-pool.story.toDebt) + " to Sabine, net " + moneyS(pool.story.net) + " · debt then " + money(cur.debtAfter), tone: "success" },
            ]}
          />
          <Table
            columns={["Movement", "Purse", "To Sabine (debt)", "Net cash", "Debt left"]}
            rows={cashMoveRows}
            align={["start", "end", "end", "end", "end"]}
          />
          {cur.wholesale ? <Text>Wholesale −20% is on for R1–R3 mods during this stop.</Text> : null}
          {retry[cur.id] ? <Text>{"A planned retry does not change the cash pool: the sim assumes a first-try win. Expected tries " + (100 / Math.max(cur.show, 0.1)).toFixed(2) + " are counted in the campaign totals only."}</Text> : null}
        </div>
        <Grid columns={2}>
          <div id="pin-inspector-facts" data-pin="pin-inspector-facts" ref={attachPin("pin-inspector-facts")} style={{ display: "flex", flexDirection: "column", gap: 12, overflowAnchor: "auto" }}>
            <Properties
              items={[
                { label: "Race", value: DNAME[cur.d] + " · " + cur.T + " turns · opponent budget " + cur.B.toFixed(1) },
                { label: "Win chance", value: pc(cur.show) + " (district average " + pc(cur.win.d) + (cur.win.h !== null ? ", hardest track " + pc(cur.win.h) : "") + ")" },
                { label: "Expected tries", value: (100 / Math.max(cur.show, 0.1)).toFixed(2) + (retry[cur.id] ? " (counted)" : " (not counted: first-try win assumed)") },
                { label: "Level", value: "L" + cur.L + " · " + Math.round(cur.bag) + " / " + Math.round(xpToNext(cur.L)) + " XP to next · cap L" + cur.capL },
                { label: "Grinds before", value: cur.grindsAuto + " automatic + " + cur.grindsExtra + " added · without them " + pc(cur.natural) + " · grind race win " + pc(cur.grindWin) },
                { label: "Cash on arrival", value: money(cur.cashBefore) + " · available to spend now " + money(pool.spendNow) + (cur.wholesale ? " · wholesale −20% on R1–R3 mods" : "") },
                { label: "Skill points", value: sp + ": POW " + share(0) + ", HAN " + share(1) + ", EN " + share(2) },
                { label: "Combat power", value: cur.power.toFixed(1) + " (base " + statsAt(cur.L).toFixed(1) + ", cap 1.07 × base " + (C.MOD_CAP * statsAt(cur.L)).toFixed(1) + ", ceiling " + stageCeil(cur.stage).toFixed(1) + ") · mod fill " + pc(100 * cur.fill) },
                { label: "r (power / budget)", value: cur.r.toFixed(4) },
                { label: "On a win", value: (cur.xp ? "+" + Math.round(cur.xp) + " XP → L" + cur.Lafter : "no story XP") + " · cash after " + usd(cur.cashAfter) + (cur.debtAfter > 0 ? " · debt left " + usd(cur.debtAfter) : "") },
                { label: "Bought at this stop", value: cur.bought.length ? cur.bought.join(", ") : "nothing" },
              ]}
            />
            <Toggle label="Plan a retry here (count expected tries)" value={!!retry[cur.id]} onChange={(v: boolean) => setRetry({ ...retry, [cur.id]: v })} />
            {cur.era === "Arc" || cur.era === "Finale" ? <Text>Arc and finale wins use the district tune, as in the sim: the skill split does not change them.</Text> : null}
          </div>
          <div id="pin-inspector-shop" data-pin="pin-inspector-shop" ref={attachPin("pin-inspector-shop")} style={{ display: "flex", flexDirection: "column", gap: 12, overflowAnchor: "auto" }}>
            <Table columns={["Slot", "Equipped (best owned per slot)", "Points"]} rows={slotRows} />
            <Select label="Buy before this race" options={shopOpts} value={shopId} onChange={(v: string) => setShopId(v)} />
            <Toggle label={"Aero version (1.75× price, one equipped max)" + (cur.aeroOpen ? "" : ": unlocks after the R1 boss")} value={shopAero && cur.aeroOpen} disabled={!cur.aeroOpen} onChange={(v: boolean) => setShopAero(v)} />
            {pickOpen ? (
              <Status tone={pickAfford ? "success" : "danger"}>{pickAfford ? "Affordable · " + money(pickPrice) : "Need " + money(pickShort) + " more"}</Status>
            ) : (
              <Status tone="warning">Locked until {unlockText(MOD[shopId].u)}</Status>
            )}
            <Button label="Add to plan" variant="primary" onClick={(ev?: any) => press("pin-inspector-shop", ev, () => setBuys([...buys, { at: cur.id, id: shopId, aero: shopAero && cur.aeroOpen }]))} />
            {hereBuys.length ? (
              <Table
                columns={["Planned here", ""]}
                rows={hereBuys.map(({ b, i }) => [modLabel(b) + " · " + money(shopPrice(b.id, b.aero)), <Button key={"x" + i} label="Remove" variant="quiet" onClick={(ev?: any) => press("pin-inspector-shop", ev, () => setBuys(buys.filter((_, k) => k !== i)))} />])}
              />
            ) : null}
            {cur.failed.length ? <Callout tone="danger" lead="Not bought">{cur.failed.join("; ")}</Callout> : null}
            <Text>Bought mods are permanent: no re-picking or selling. Buys run after this race's grinds, just before it starts. Power is capped at min(round or finale ceiling, 1.07 × base, skill points + slot points).</Text>
          </div>
        </Grid>
        </div>
      </Section>

      <Section heading="Race by race" id="race-by-race" caption="State on arrival at each race, after its grinds and buys. Win chance = the lower of the district average and the hardest track (bosses and finale use the hardest track). Without its grinds is the chance on arrival if you skipped that race's grinds. Held up by grinds = under the target without them; Naturally high = 25+ points over the target without grinding. Click a race to inspect it, buy mods or plan a retry.">
        <Table columns={["Race", "District · length", "Grinds before (− / +)", "Level", "Cash", "Power", "r", "Without its grinds", "Win", "vs target", "Tries"]} rows={ladderRows} align={["start", "start", "start", "end", "end", "end", "end", "end", "end", "start", "end"]} />
      </Section>

      <Section heading="Campaign at a glance">
        <div style={{ overflowAnchor: "none" }}>
          <Metrics
            metrics={[
              { value: pc(lowLadder.show), label: "Lowest R1–R3 race", detail: raceName(lowLadder), tone: toneOf(lowLadder.show) },
              { value: f1(ladder.filter((r) => r.boss).map((r) => r.show)), label: "Bosses R1 / R2 / R3" },
              { value: pc(lowArc.show), label: "Lowest arc race", detail: raceName(lowArc), tone: toneOf(lowArc.show) },
              { value: f1(fin.map((r) => r.show)), label: "Finale F1–F4" },
              { value: String(gAuto + gMine), label: "Grind races", detail: gAuto + " automatic, " + gMine + " added by you; " + heldN + " races only reach " + target + "% because of grinds" },
              { value: usd(last.cashAfter), label: "Cash after F4", detail: "Level " + last.Lafter + ", " + (rows.length + gAuto + gMine + extraTries).toFixed(1) + " races incl. expected retries" },
            ]}
          />
          <LineChart points={rows.map((r) => ({ label: r.id, value: r.show }))} ceiling={100} floor={0} unit="%" labels={["Win chance per story race"]} />
        </div>
      </Section>

      <Section heading="Rules used" collapsible defaultOpen={false}>
        <Rows
          rows={[
            { title: "Win chance", detail: "Expected values from the sim's live win tables (5 tracks per district, linear in r), with the POW-share adjustment off the district tune. Each race is assumed won first try." },
            { title: "XP", detail: "100 × 1.08^L per level. Grinds are 10-turn races paying 70% of a level, tapering near the cap. Leftover XP carries over between rounds (live sim): a story race pays its nominal XP as if entered at the previous cap, plus 75% of the shortfall split Kid 1 40% / Kid 2 40% / Mature 1 20%; R2 boss XP × 1.5. XP past a cap is lost." },
            { title: "Cash", detail: "Wild $1,000, crew $2,500, boss $8,000 × 1 / 1.15 / 1.35 by round; grinds pay 55% of a wild purse. 65% of every purse repays the $16,000 debt until it is cleared. Arc purses $2,500 / $3,375 / $5,000 by length, finale $10,800, arc grinds $742.50." },
            { title: "Mods", detail: "4 slots (Street and Touge: POW, POW, HAN, EN; Wangan: POW, HAN, EN, EN). Unlocks: Mk1 at round start, Mk2 after Mature 1, Mk3 after Mature 2, Myth1 after P1, Myth2–4 after F1–F3. Wholesale −20% on R1–R3 mods during R2 and R3. Aero from the R1 boss on, 1.75× price, one equipped; it adds no extra power in the win model." },
            { title: "Skill points", detail: "round(2400 × 1.1^(L/12)) points; base power = points / 8. 25–50% per stat; 20% of spent points may move at each district change." },
            { title: "Grinds", detail: "The sim has one kind of grind per stage (10 turns, district average, against the Kid 1 budget in rounds, at r 1.12 in the arc), so there is no track or length choice." },
          ]}
        />
      </Section>

      <Section heading="Verified against sim">
        <Table columns={["Check", "Python sim", "This page (JS, live)", ""]} rows={vRows} />
        <Text>Verified against the live sim on proto-build (2026-11-14, with leftover XP carry-over live). Tables are generated from the Python source by unapproved/barry/planner-v1/gen_constants.py. On the story, mixed and hard walks and the arc, 622 win cells were compared: 605 exact, 17 within 0.1 pp (rounding of the stored table values). Levels, cash and grind counts are identical.</Text>
      </Section>
    </Page>
  );
}
